En C#, el patrón Builder se utiliza para crear objetos complejos a partir de otros objetos más simples. Esto se logra mediante la creación de una clase que reciba los datos y los use para crear el objeto completo.

Aquí hay un ejemplo de implementación del patrón Builder en C#:

using System;

namespace BuilderPatternExample
{
    class Program
    {
        static void Main(string[] args)
        {
            // Crear un objeto Builder
            Builder builder = new Builder();

            // Crear un objeto completo
            Order order = builder.BuildOrder();

            // Imprimir el objeto completo
            Console.WriteLine(order);

            Console.ReadKey();
        }
    }

    class Order
    {
        public string Name { get; set; }
        public decimal Price { get; set; }
    }

    class Builder
    {
        // Atributo que almacena el objeto completo
        Order order = new Order();

        // Método que crea el objeto completo
        public Order BuildOrder()
        {
            return order;
        }

        // Método que crea el nombre del objeto
        public Builder WithName(string name)
        {
            order.Name = name;
            return this;
        }

        // Método que crea el precio del objeto
        public Builder WithPrice(decimal price)
        {
            order.Price = price;
            return this;
        }
    }
}


