```java
import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class AccelerometerIntegration {
    public static void main(String[] args) throws IOException {
        // Lesen der Beschleunigungsdaten aus der Datei
        List<Double> accelerometerData = readAccelerometerData("accData.txt");

        // Berechnung der Position
        double xPos = integrateAcceleration(accelerometerData, 0);
        double yPos = integrateAcceleration(accelerometerData, 1);
        double zPos = integrateAcceleration(accelerometerData, 2);

        // Ausgabe der Position
        System.out.println("Position X: " + xPos);
        System.out.println("Position Y: " + yPos);
        System.out.println("Position Z: " + zPos);
    }

    // Integration der Beschleunigungsdaten
    private static double integrateAcceleration(List<Double> accelerometerData, int axis) {
        double integration = 0;
        for (Double acceleration : accelerometerData) {
            integration += acceleration * (axis + 1);
        }
        return integration / (accelerometerData.size() + 1);
    }

    // Lesen der Beschleunigungsdaten aus der Datei
    private static List<Double> readAccelerometerData(String fileName) throws IOException {
        List<Double> accelerometerData = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(fileName))) {
            String line;
            while ((line = reader.readLine())!= null) {
                accelerometerData.add(Double.parseDouble(line));
            }
        }
        return accelerometerData;
    }
}
